    m, n = len(A), len(A[0])
    for i in range(m):
        max_row = i + max(range(i, m), key=lambda r: abs(A[r][i]))
        A[i], A[max_row] = A[max_row], A[i]
        if A[i][i] == 0:
            continue
        for j in range(n):
            A[i][j] /= A[i][i]
        for k in range(m):
            if k != i and A[k][i] != 0:
                factor = A[k][i]
                for j in range(n):
                    A[k][j] -= factor * A[i][j]
    return A

def rank_of_matrix(A):
    m, n = len(A), len(A[0])
    reduced_A = gaussian_elimination(A)
    rank = sum(1 for row in reduced_A if any(row[j] != 0 for j in range(n)))
    return rank

